def build_markdown():
    lines = []
    lines.append("---")
    lines.append('id: vocab-awl-500')
    lines.append('title: "Academic Word List (AWL) 500 Root Corpus"')
    lines.append('category: "ACADEMIC_WORD_LIST"')
    lines.append(f"totalItems: {len(ITEMS)}")
    lines.append('description: "500 high-yield Academic Word List entries structured by Greco-Latin roots, phonetics, definitions, Vietnamese translations, and academic collocations."')
    lines.append("---\n")
    lines.append("# Academic Word List (AWL) 500 Root Corpus\n")
    lines.append("| Index | Word | POS | IPA | Root Family | Definition | Vietnamese Meaning | Collocations |")
    lines.append("| :---: | :--- | :---: | :--- | :--- | :--- | :--- | :--- |")

    seen_words = set()
    for idx, item in enumerate(ITEMS, 1):
        word, pos, ipa, root, definition, vn, colloc = item
        # Validation checks
        if word in seen_words:
            print(f"ERROR: Duplicate word '{word}' at index {idx}", file=sys.stderr)
            sys.exit(1)
        seen_words.add(word)

        # Sanitize pipes
        clean_root = root.replace("|", "/")
        clean_def = definition.replace("|", "/")
        clean_vn = vn.replace("|", "/")
        clean_colloc = colloc.replace("|", "/")

        row = f"| {idx} | {word} | {pos} | {ipa} | {clean_root} | {clean_def} | {clean_vn} | {clean_colloc} |"
        lines.append(row)

    content = "\n".join(lines) + "\n"
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        f.write(content)

    print(f"[SUCCESS] Compiled {len(ITEMS)} unique AWL items into {OUTPUT_PATH}")

if __name__ == "__main__":
    if len(ITEMS) != 500:
        print(f"ERROR: Expected exactly 500 items, got {len(ITEMS)}", file=sys.stderr)
        sys.exit(1)
    build_markdown()
